<script setup lang="ts">
import {ref,onMounted,onUnmounted,computed} from 'vue'
import {Plus,RefreshCw,Play,Archive,Link,Copy} from '@lucide/vue'
import {api,APIError,type PersistentWorkspace,type Conversation,type LogicalNamespace,type RunContext} from './api'
const props=defineProps<{token:string;projectId:string;enabled:boolean;images:string[];maxTtl:number}>()
const emit=defineEmits<{expired:[];start:[workspace:PersistentWorkspace];open:[id:string,run?:RunContext]}>()
const namespace=ref<LogicalNamespace|null>(null),items=ref<PersistentWorkspace[]>([]),conversations=ref<Conversation[]>([])
const busy=ref(false),error=ref(''),notice=ref(''),view=ref('workspaces'),filter=ref('active'),modal=ref(''),name=ref(''),integration=ref('local-ai'),external=ref(''),requestKey=ref('')
const runs=ref<RunContext[]>([]),continuing=ref<Conversation|null>(null),runtimeImage=ref(''),runtimeTtl=ref(3600)
const runStates:Record<string,string>={Preparing:'准备中',Waiting:'等待核对',Ready:'可使用',Failed:'准备失败',Released:'执行已结束',Invalidated:'实例已结束'}
function currentRun(c:Conversation){return runs.value.find(r=>r.conversationId===c.id&&!r.releasedAt)||runs.value.find(r=>r.conversationId===c.id)}
const choices=ref<Record<string,string>>({}),resolved=ref('')
const visible=computed(()=>items.value.filter(w=>filter.value==='all'||(filter.value==='archived'?!!w.archivedAt:!w.archivedAt)))
const states:Record<string,string>={Creating:'准备存储',Available:'可使用',Error:'存储异常'}
let alive=true
async function perform(fn:()=>Promise<void>,quiet=false){if(busy.value||!alive)return;busy.value=true;if(!quiet){error.value='';notice.value='';}try{await fn()}catch(e){if(!alive)return;if(e instanceof APIError&&e.status===401)emit('expired');error.value=e instanceof APIError&&e.status===409&&!e.reason?'状态或版本已变化，或工作区正在使用／配额已满。请刷新后重试。':e instanceof Error?e.message:String(e)}finally{busy.value=false}}
async function load(){const p=props.projectId;const [n,ws,cs,rs]=await Promise.all([api<LogicalNamespace>('namespace/current',props.token),api<PersistentWorkspace[]>('workspace/list',props.token,{projectId:p}),api<Conversation[]>('conversation/list',props.token,{projectId:p}),api<RunContext[]>('run/list',props.token,{projectId:p})]);if(!alive||p!==props.projectId)return;namespace.value=n;items.value=ws;runs.value=rs;const previous=conversations.value;conversations.value=cs;for(const c of cs){if(!(c.id in choices.value)||previous.find(old=>old.id===c.id)?.version!==c.version)choices.value[c.id]=c.workspaceId}}
function create(kind:string){modal.value=kind;name.value='';external.value='';requestKey.value=crypto.randomUUID()}
async function save(){await perform(async()=>{if(modal.value==='continue'&&continuing.value){await api<RunContext>('conversation/continue',props.token,{conversationId:continuing.value.id,expectedVersion:continuing.value.version,image:runtimeImage.value,ttl:runtimeTtl.value,requestKey:requestKey.value});notice.value='运行准备已登记，关闭页面后仍会继续核对。';modal.value='';await load();return;}if(modal.value==='workspace'){await api('workspace/create',props.token,{projectId:props.projectId,name:name.value,requestKey:requestKey.value});notice.value='工作区已登记，存储准备状态将持续同步。'}else{await api('conversation/register',props.token,{projectId:props.projectId,integrationId:integration.value,externalId:external.value,title:name.value});notice.value='对话引用已保存。聊天内容仍由原客户端保存。'}modal.value='';await load()})}
async function action(w:PersistentWorkspace,a:string){await perform(async()=>{await api('workspace/action',props.token,{id:w.id,action:a});await load();notice.value=a==='archive'?'已归档，数据继续保留。':a==='unarchive'?'已取消归档。':'存储状态已同步。'})}
async function bind(c:Conversation){await perform(async()=>{await api('conversation/workspace',props.token,{id:c.id,workspaceId:choices.value[c.id]||'',expectedVersion:c.version});await load();notice.value='对话绑定已保存；解除或更换绑定不会删除原数据。'})}
async function resolve(c:Conversation){await perform(async()=>{const r=await api<{workspace:PersistentWorkspace|null;sandbox:{id:string}|null;history:unknown[]}>('conversation/resolve',props.token,{id:c.id});resolved.value=JSON.stringify(r,null,2);if(r.workspace)notice.value=`已定位到 ${r.workspace.name}，PVC：${r.workspace.pvcName}。${r.sandbox?'当前有运行实例。':'需要运行时可从工作区启动。'}`;else notice.value='该对话尚未绑定工作区。'})}
function continueConversation(c:Conversation){continuing.value=c;runtimeImage.value=props.images[0]||'';runtimeTtl.value=Math.min(3600,props.maxTtl);requestKey.value=crypto.randomUUID();error.value='';modal.value='continue'}
async function releaseRun(r:RunContext){if(!confirm('结束本次执行后，旧上下文将失效。沙箱、后台服务和工作区文件仍保留；要停止计算，请在实例页销毁沙箱。'))return;await perform(async()=>{await api('run/release',props.token,{id:r.id});await load();notice.value='本次执行已结束，工作区文件继续保留。'})}
async function copy(s:string){try{await navigator.clipboard.writeText(s);notice.value='已复制'}catch{error.value='复制失败，请手动复制'}}
onMounted(()=>void perform(load))
let lastPoll=0
let timer=setInterval(()=>{const interval=view.value==='conversations'&&runs.value.some(r=>!r.releasedAt)?3000:15000;if(!busy.value&&Date.now()-lastPoll>=interval){lastPoll=Date.now();void perform(load,true)}},1000)
onUnmounted(()=>{alive=false;clearInterval(timer)})
</script>
<template>
<div class="persistent-panel">
<div class="summary"><span>个人 Namespace <strong class="mono">{{namespace?.name||'加载中'}}</strong></span><small>逻辑数据空间 · 每个工作区独立保存文件 · 非 Kubernetes Namespace</small></div>
<p>所有个人工作区归属同一逻辑空间，列表按当前项目和权限展示。停止沙箱、闲置或归档都会保留工作区数据。</p>
<div v-if="error" class="error" role="alert">{{error}}</div><div v-if="notice" class="notice" role="status">{{notice}}</div>
<div class="toolbar"><div class="context"><button :aria-pressed="view==='workspaces'" @click="view='workspaces'">持久化工作区</button><button :aria-pressed="view==='conversations'" @click="view='conversations'">对话关联</button><select v-if="view==='workspaces'" v-model="filter" aria-label="工作区范围"><option value="active">未归档</option><option value="archived">已归档</option><option value="all">全部</option></select></div><div class="actions"><button class="icon" :disabled="busy" aria-label="刷新工作区" @click="perform(load)"><RefreshCw :size="15"/></button><button class="primary" :disabled="busy||(view==='workspaces'&&!enabled)" @click="create(view==='workspaces'?'workspace':'conversation')"><Plus :size="15"/>{{view==='workspaces'?'新建工作区':'登记对话'}}</button></div></div>
<p v-if="!enabled">当前未启用集群存储连接，已有工作区仍可查看。</p>
<div v-if="view==='workspaces'" class="table-wrap"><table><thead><tr><th>名称 / 所有者</th><th>数据状态</th><th>运行实例</th><th>申请容量</th><th>操作</th></tr></thead><tbody><tr v-for="w in visible" :key="w.id"><td><strong>{{w.name}}</strong><small>{{w.ownerId}} · {{w.archivedAt?'已归档':'长期保留'}}</small><small class="mono">{{w.id}} <button class="text" aria-label="复制工作区 ID" @click="copy(w.id)"><Copy :size="12"/></button></small></td><td><span class="status" :class="w.state.toLowerCase()">{{states[w.state]||w.state}} / {{w.storagePhase}}</span><small class="wrap-cell">{{w.message}}</small><small class="mono">PVC: {{w.pvcName}}</small><small v-if="w.pvName" class="mono">PV: {{w.pvName}}</small></td><td><button v-if="w.activeSandboxId" class="text name" @click="emit('open',w.activeSandboxId)">查看实例</button><span v-else>已停止</span></td><td>{{w.requestedBytes/1024**3}} GiB<small>实际用量未知</small></td><td><div class="actions"><button :disabled="busy||!enabled||w.state!=='Available'||!!w.archivedAt||!!w.activeSandboxId" @click="emit('start',w)"><Play :size="14"/>启动</button><button :disabled="busy" @click="action(w,'sync')">同步</button><button :disabled="busy||!!w.activeSandboxId" @click="action(w,w.archivedAt?'unarchive':'archive')"><Archive :size="14"/>{{w.archivedAt?'取消归档':'归档'}}</button></div></td></tr><tr v-if="!visible.length"><td colspan="5" class="empty-cell">暂无工作区。创建后可在多个沙箱之间复用原文件。</td></tr></tbody></table></div>
<template v-else><p>对话只引用工作区。多个对话绑定同一工作区会共用当前文件；同一工作区只允许一个主动执行。更换绑定前须结束执行并停止相关实例。后台服务可能持续写文件，结束执行不会停止后台服务。</p><div class="table-wrap"><table><thead><tr><th>对话</th><th>所有者 / 来源</th><th>当前工作区</th><th>运行准备</th><th>操作</th></tr></thead><tbody><tr v-for="c in conversations" :key="c.id"><td>{{c.title}}<small class="mono">{{c.externalId}}</small></td><td>{{c.ownerId}}<small>{{c.integrationId}} · 版本 {{c.version}}</small></td><td><select v-model="choices[c.id]" :aria-label="'对话 '+c.title+' 的工作区'"><option value="">不绑定</option><option v-for="w in items.filter(w=>w.ownerId===c.ownerId&&!w.archivedAt)" :key="w.id" :value="w.id">{{w.name}}</option></select></td><td><template v-if="currentRun(c)"><span class="status" :class="currentRun(c)!.state==='Ready'?'running':'pending'">{{runStates[currentRun(c)!.state]}}</span><small class="wrap-cell">{{currentRun(c)!.message}}</small><small>已核对 {{currentRun(c)!.operation.attempt}} 次</small></template><span v-else>未开始</span></td><td><div class="actions"><button class="primary" v-if="!currentRun(c)||currentRun(c)!.releasedAt" :disabled="busy||!enabled||!c.workspaceId" @click="continueConversation(c)"><Play :size="14"/>继续使用</button><button v-if="currentRun(c)?.state==='Ready'" :disabled="busy" @click="emit('open',currentRun(c)!.sandboxId,currentRun(c))">进入实例</button><button v-if="currentRun(c)?.state==='Ready'" :disabled="busy" @click="releaseRun(currentRun(c)!)">结束执行</button><button v-if="currentRun(c)?.sandboxId&&currentRun(c)?.state!=='Ready'&&!currentRun(c)?.releasedAt" :disabled="busy" @click="emit('open',currentRun(c)!.sandboxId)">查看实例</button><button :disabled="busy||choices[c.id]===c.workspaceId" @click="bind(c)"><Link :size="14"/>保存绑定</button><button :disabled="busy" @click="resolve(c)">定位数据</button></div></td></tr><tr v-if="!conversations.length"><td colspan="5" class="empty-cell">登记本地 AI 的稳定对话 ID，再选择工作区。</td></tr></tbody></table></div><pre v-if="resolved" class="output" aria-label="对话定位与绑定历史">{{resolved}}</pre></template>
<div v-if="modal" class="modal-backdrop" @click.self="!busy&&(modal='')"><form class="modal" @submit.prevent="save"><h2>{{modal==='continue'?'继续使用 · '+continuing?.title:modal==='workspace'?'新建持久工作区':'登记外部对话引用'}}</h2><template v-if="modal==='continue'"><label>镜像<select v-model="runtimeImage"><option v-for="i in images" :key="i" :value="i">{{i}}</option></select></label><label>新实例存活时间（秒）<input v-model.number="runtimeTtl" type="number" min="60" :max="maxTtl" required/></label><p>将复用可用实例，或挂载原工作区创建新实例。复用不会自动续期。准备进度会保存在平台。</p></template><template v-else><label>名称<input v-model="name" required :maxlength="modal==='workspace'?80:160"/></label><template v-if="modal==='conversation'"><label>客户端来源<input v-model="integration" required maxlength="80"/></label><label>外部对话 ID<input v-model="external" required maxlength="255"/></label><p>仅保存你自己的对话引用，不读取聊天内容，也不以该 ID 作为访问凭证。</p></template><p v-else>工作区归属你的个人 Namespace，申请 10Gi 存储。只有 /workspace 中的文件会保留，运行进程和系统依赖需要重新启动或安装。</p></template><div v-if="error" class="error" role="alert">{{error}}</div><div class="actions"><button type="button" :disabled="busy" @click="modal=''">取消</button><button class="primary" :disabled="busy">{{busy?'处理中…':'保存'}}</button></div></form></div>
</div>
</template>
<style scoped>
.wrap-cell{white-space:normal;max-width:260px}.persistent-panel{min-width:0}.context [aria-pressed="true"]{color:#245db5;border-color:#7598cc;background:#f1f6ff}.table-wrap{max-height:62vh}.persistent-panel>p{margin:12px 0}
</style>
